package com.worksphere.controller; import com.worksphere.dto.profile.*; import com.worksphere.service.WorkerProfileService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/users/me/worker-profile") public class WorkerProfileController {private final WorkerProfileService s;public WorkerProfileController(WorkerProfileService x){s=x;} @GetMapping public WorkerProfileResponse get(Authentication a){return s.get(a);} @PutMapping public WorkerProfileResponse save(Authentication a,@RequestBody WorkerProfileRequest r){return s.save(a,r);} }
